import { create_list_delete_tags } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deletetagDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    deletetagDialog: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_delete_tags, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "DELETE_TAGS",
            tag_id: this.rowInfo.tag_id,
            tag_status: "DEACTIVE"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_delete_tags);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
